import type { DesignContent } from "@/lib/design-content";

export const content: DesignContent = {"slug": "log-in", "title": "Log in · UniShare", "css": "\n:root{--teal:#0f6b63;--ink:#171c1b;--muted:#4b5552;--line:#111;--tint:#e7f0ee;--field:#fff}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"DM Sans\",system-ui,sans-serif;color:var(--ink);background:#fff;line-height:1.5;min-height:100vh;display:flex;flex-direction:column}\na{text-decoration:none;color:inherit}\n.wrap{width:100%;max-width:1000px;margin:0 auto;padding:0 24px}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 20px;border-radius:6px;font-size:15px;font-weight:500;border:1.5px solid var(--teal);background:var(--teal);color:#fff;cursor:pointer;white-space:nowrap;font-family:inherit}\n.btn.block{width:100%;padding:14px;font-size:16px}\n.btn.sm{padding:9px 16px;font-size:14px}\nheader{border-bottom:1.5px solid var(--line)}\nheader .wrap{display:flex;justify-content:space-between;align-items:center;height:68px}\n.logo{display:flex;align-items:center;gap:8px;font-weight:700;font-size:18px}\nnav{display:flex;align-items:center;gap:24px;font-size:14px}\nnav .link{color:var(--ink);font-weight:500}\n\n.main{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;padding:64px 0 72px;flex:1}\n.eyebrow{font-size:12px;font-weight:700;letter-spacing:.06em;color:var(--teal);text-transform:uppercase}\nh1{font-size:44px;line-height:1.1;font-weight:700;letter-spacing:-.02em;margin:12px 0 18px}\nh1 em{font-style:normal;color:var(--teal)}\n.lead{color:var(--muted);font-size:16px;max-width:400px}\n\n.tiles{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:32px;max-width:440px}\n.tile{position:relative;aspect-ratio:1/1;border:1.5px solid var(--line);border-radius:10px;overflow:hidden;background:#dfe6e3}\n.tile.wide{aspect-ratio:auto}\n.tile img{width:100%;height:100%;object-fit:cover;display:block}\n.tag{position:absolute;left:8px;bottom:8px;background:#fff;border:1.5px solid var(--line);border-radius:999px;padding:2px 10px;font-size:12px;font-weight:500}\n.caption{font-size:13px;color:var(--muted);margin-top:14px}\n\n.card{border:1.5px solid var(--line);border-radius:12px;padding:36px 36px 28px;box-shadow:8px 8px 0 var(--teal);background:#fff}\n.card h2{font-size:30px;font-weight:700;letter-spacing:-.01em}\n.sub{color:var(--muted);font-size:15px;margin:8px 0 26px}\n.field{margin-bottom:20px}\n.field label{display:block;font-size:14px;font-weight:700;margin-bottom:8px}\n.input{position:relative}\n.input input{width:100%;height:48px;padding:0 44px 0 14px;border:1.5px solid var(--line);border-radius:6px;background:var(--field);font:inherit;font-size:15px;color:var(--ink)}\n.input input:focus{outline:2px solid var(--teal);outline-offset:1px}\n.input svg{position:absolute;right:14px;top:50%;transform:translateY(-50%);width:18px;height:18px;stroke:var(--ink);fill:none;stroke-width:1.8}\n.row{display:flex;justify-content:space-between;align-items:center;margin:4px 0 24px;font-size:14px}\n.keep{display:flex;align-items:center;gap:8px;color:var(--muted)}\n.keep input{width:16px;height:16px;accent-color:var(--teal)}\n.forgot{color:var(--teal);font-weight:700}\n.card .btn.block{margin-bottom:18px}\n.new{text-align:center;font-size:14px;color:var(--muted);margin-bottom:22px}\n.new a{color:var(--teal);font-weight:700}\n.notice{display:flex;gap:12px;background:var(--tint);border-radius:8px;padding:16px 18px}\n.notice svg{flex:none;width:20px;height:20px;stroke:var(--teal);fill:none;stroke-width:1.8;margin-top:1px}\n.notice strong{display:block;color:var(--teal);font-size:14px}\n.notice small{display:block;font-size:13px;color:var(--muted);margin-top:2px}\n\nfooter{border-top:1.5px solid var(--line);padding:22px 0}\nfooter .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13px;color:var(--muted)}\nfooter .links{display:flex;gap:24px;color:var(--teal);font-weight:700}\n\n@media (max-width:820px){\n  .main{grid-template-columns:1fr;gap:44px;padding:44px 0 56px}\n  h1{font-size:36px}\n}\n@media (max-width:480px){\n  .card{padding:28px 22px}\n  .card h2{font-size:26px}\n  h1{font-size:32px}\n}\n", "body": "\n\n<header>\n  <div class=\"wrap\">\n    <a class=\"logo\" href=\"/\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#171c1b\" stroke-width=\"2\"><circle cx=\"8\" cy=\"12\" r=\"5\"/><circle cx=\"16\" cy=\"12\" r=\"5\"/></svg>\n      UniShare\n    </a>\n    <nav>\n      <a class=\"link\" href=\"/log-in\">Log in</a>\n      <a class=\"btn sm\" href=\"/create-account\">Create account</a>\n    </nav>\n  </div>\n</header>\n\n<main class=\"wrap main\">\n  <section>\n    <p class=\"eyebrow\">Good to have you back</p>\n    <h1>Your campus.<br><em>Still sharing.</em></h1>\n    <p class=\"lead\">A calculator for the exam. A football for the weekend. A ride to your next class. It’s all closer than you think.</p>\n\n    <div class=\"tiles\">\n      <div class=\"tile\"><img src=\"data:image/jpeg;base64,\" alt=\"Calculator\"><span class=\"tag\">Calculator</span></div>\n      <div class=\"tile\"><img src=\"data:image/jpeg;base64,\" alt=\"Footballs\"><span class=\"tag\">Football</span></div>\n      <div class=\"tile\"><img src=\"data:image/jpeg;base64,\" alt=\"Laptop charger\"><span class=\"tag\">Laptop charger</span></div>\n      <div class=\"tile\"><img src=\"data:image/jpeg;base64,\" alt=\"Car ride\"><span class=\"tag\">Car ride</span></div>\n    </div>\n    <p class=\"caption\">Only your university. Only verified students.</p>\n  </section>\n\n  <section class=\"card\">\n    <h2>Welcome back</h2>\n    <p class=\"sub\">Log in to your UniShare account with your university email.</p>\n\n    <form onsubmit=\"return false\">\n      <div class=\"field\">\n        <label for=\"email\">University email</label>\n        <div class=\"input\">\n          <input id=\"email\" type=\"email\" value=\"farhana@std.du.ac.bd\" autocomplete=\"email\">\n          <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"1.5\"/><path d=\"M3 6l9 7 9-7\"/></svg>\n        </div>\n      </div>\n\n      <div class=\"field\">\n        <label for=\"pw\">Password</label>\n        <div class=\"input\">\n          <input id=\"pw\" type=\"password\" value=\"password1234\" autocomplete=\"current-password\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M3 3l18 18M10.6 6.1A9.8 9.8 0 0 1 12 6c5 0 8.5 4.5 9.5 6-.4.7-1.1 1.7-2.1 2.7M6.6 6.7C4.3 8.2 2.8 10.3 2.5 12c1 1.5 4.5 6 9.5 6 1.5 0 2.9-.4 4.1-1\"/><path d=\"M9.9 9.9a3 3 0 0 0 4.2 4.2\"/></svg>\n        </div>\n      </div>\n\n      <div class=\"row\">\n        <label class=\"keep\"><input type=\"checkbox\" checked> Keep me logged in</label>\n        <a class=\"forgot\" href=\"/forgot-password\">Forgot password?</a>\n      </div>\n\n      <button class=\"btn block\" type=\"submit\">Log in\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg>\n      </button>\n\n      <p class=\"new\">New to UniShare? <a href=\"/create-account\">Create account</a></p>\n    </form>\n\n    <div class=\"notice\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M12 3l8 3v6c0 4.5-3.4 8-8 9-4.6-1-8-4.5-8-9V6z\"/><path d=\"M9 12l2 2 4-4\"/></svg>\n      <div>\n        <strong>Not verified yet? No worries.</strong>\n        <small>Log in to finish your student verification or check whether your submission is still under review.</small>\n      </div>\n    </div>\n  </section>\n</main>\n\n<footer>\n  <div class=\"wrap\">\n    <span>UniShare. Made for university students in Bangladesh.</span>\n    <span class=\"links\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/get-help\">Get help</a></span>\n  </div>\n</footer>\n\n", "scripts": [], "fonts": ["https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&display=swap"]};

